<!DOCTYPE html>
<html lang="pt-BR"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
<meta name="description" content="Diário de exploração do modpack Imperacraft: checklist de mods, bosses, dungeons e atividades por fase de jogo.">
<meta name="theme-color" content="#09130e">
<title>Imperacraft – Diário de Exploração</title>
<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Cinzel:wght@600;800&display=swap">
<style>
:root{--bg:#efeadb;--sf:#fffdf4;--s2:#f5efd9;--bd:#d6cfb2;--tx:#1b2a21;--mu:#5c6a5e;--gd:#a67a0a;--ac:#2f7d4f;--bl:30%;--hb:linear-gradient(180deg,#f3ecd0,#efeadb);box-sizing:border-box;padding-top:env(safe-area-inset-top,0px);padding-bottom:env(safe-area-inset-bottom,0px)}
@media(prefers-color-scheme:dark){:root:not([data-theme="light"]){--bg:#09130e;--sf:#112019;--s2:#16291f;--bd:#27402f;--tx:#ece8d6;--mu:#9bad9d;--gd:#e8b93c;--ac:#3fb06c;--bl:70%;--hb:radial-gradient(900px 300px at 20% 0,#1d3a28,#09130e);color-scheme:dark}}
:root[data-theme="dark"]{--bg:#09130e;--sf:#112019;--s2:#16291f;--bd:#27402f;--tx:#ece8d6;--mu:#9bad9d;--gd:#e8b93c;--ac:#3fb06c;--bl:70%;--hb:radial-gradient(900px 300px at 20% 0,#1d3a28,#09130e);color-scheme:dark}
html{scroll-padding-top:calc(env(safe-area-inset-top,0px) + 120px)}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--tx);font:15px/1.45 system-ui,-apple-system,"Segoe UI",sans-serif}
.ct{max-width:980px;margin:0 auto;padding:0 16px}
.hero{background:var(--hb);border-bottom:2px solid var(--gd);padding:22px 0}
.hg{display:grid;grid-template-columns:200px 1fr;gap:20px;align-items:center}
.hg img{width:200px;height:200px;object-fit:cover;border-radius:14px;border:2px solid var(--gd);box-shadow:0 6px 24px #0006}
h1{font:800 clamp(26px,5vw,42px)/1.05 Cinzel,Georgia,serif;margin:0;color:var(--gd);letter-spacing:1px}
.tg{font:600 13px Cinzel,Georgia,serif;letter-spacing:2px;color:var(--mu);text-transform:uppercase;margin:6px 0 14px}
.st{display:flex;gap:14px;align-items:center;flex-wrap:wrap}
.ring{width:84px;height:84px;border-radius:50%;display:grid;place-items:center;background:conic-gradient(var(--gd) var(--p,0%),var(--bd) 0)}
.ring b{width:66px;height:66px;border-radius:50%;background:var(--bg);display:grid;place-items:center;font:800 18px Cinzel,Georgia,serif}
.ph{flex:1;min-width:220px;display:grid;gap:5px}.pr{display:grid;grid-template-columns:62px 1fr 56px;gap:8px;align-items:center;font-size:12px;color:var(--mu)}
.bar{height:7px;border-radius:5px;background:var(--bd);overflow:hidden}.bar i{display:block;height:100%;width:0;background:hsl(var(--h,140) 60% 45%);transition:width .25s}
.pE{--h:140}.pM{--h:205}.pL{--h:28}.pX{--h:320}
.tb{position:sticky;top:env(safe-area-inset-top,0px);z-index:9;background:var(--bg);border-bottom:1px solid var(--bd);padding:10px 0}
.row{display:flex;gap:6px;flex-wrap:wrap;margin-top:7px;align-items:center}.row:first-child{margin-top:0}
input[type=search],select{padding:7px 10px;border:1px solid var(--bd);border-radius:8px;background:var(--sf);color:var(--tx);font:inherit}
input[type=search]{flex:1;min-width:170px}
button,.chip{border:1px solid var(--bd);background:var(--sf);color:var(--tx);border-radius:999px;padding:4px 11px;font:inherit;font-size:13px;cursor:pointer}
button:hover,.chip:hover{border-color:var(--gd)}.chip.on{background:var(--gd);color:#fff;border-color:var(--gd);font-weight:600}
.gold{background:var(--gd);color:#fff;border-color:var(--gd);font-weight:600}
#fp,#ft,#fs,#fc{display:flex;flex-wrap:wrap;gap:6px 6px;align-items:center}.chip{display:inline-block;white-space:nowrap;line-height:1.4}.tb .row{gap:6px 10px}
@media(max-width:620px){.tb{position:static}}
.lb{font-size:11px;color:var(--mu);text-transform:uppercase;letter-spacing:1px;margin-right:2px}
h2{font:800 17px Cinzel,Georgia,serif;color:var(--gd);margin:26px 0 8px;display:flex;justify-content:space-between;border-bottom:1px solid var(--bd);padding-bottom:5px}
h2 span{font:13px system-ui;color:var(--mu)}
.mc{background:var(--sf);border:1px solid var(--bd);border-left:4px solid var(--ac);border-radius:10px;margin:8px 0;overflow:hidden}
.mc.full{border-left-color:var(--gd);background:var(--s2)}
.mh{display:flex;gap:10px;align-items:center;padding:9px 12px;cursor:pointer}.mh:hover{background:var(--s2)}
.nm{font-weight:700;color:inherit;text-decoration:none}.nm:hover{text-decoration:underline}
.ds{color:var(--mu);font-size:12.5px}.sp{flex:1;min-width:0}.mp{width:70px}.mp+small{color:var(--mu);font-size:12px;min-width:34px;text-align:right}
.mc.col .acts{display:none}.acts{padding:0 12px 8px}
.tl{display:flex;gap:6px;margin:0 0 4px}.tl button{font-size:12px;padding:2px 9px}
label.a{display:flex;gap:8px;align-items:flex-start;padding:6px 4px;border-top:1px solid var(--bd);cursor:pointer;border-radius:6px}
label.a.done .tx{text-decoration:line-through;color:var(--mu)}label.a.fl{animation:fl 1.6s}
@keyframes fl{0%,60%{background:color-mix(in srgb,var(--gd) 35%,transparent)}}
input[type=checkbox]{width:18px;height:18px;margin-top:1px;accent-color:var(--gd);flex:none}
.b{flex:none;font-size:11px;font-weight:700;padding:1px 7px;border-radius:999px;margin-top:2px;background:hsl(var(--h) 60% 50%/.2);color:hsl(var(--h) 55% var(--bl))}
.ty{flex:none;font-size:11px;margin-top:2px;color:var(--mu)}
details{margin:26px 0;color:var(--mu);font-size:13px}summary{cursor:pointer}details a{color:var(--mu)}
dialog{width:min(560px,92vw);background:var(--sf);color:var(--tx);border:1px solid var(--gd);border-radius:12px}dialog textarea{width:100%;height:160px;background:var(--bg);color:var(--tx);border:1px solid var(--bd);border-radius:8px;font:12px monospace}
@media(max-width:620px){.hg{grid-template-columns:1fr}.hg img{width:150px;height:150px}}
</style></head><body>
<header class="hero"><div class="ct hg"><img alt="Imperacraft Modpack – pantera negra na selva" src="data:image/jpeg;base64,">
<div><h1>IMPERACRAFT</h1><div class="tg">Restaure o império, domine a selva</div>
<div class="st"><div class="ring" id="rg"><b id="rp">0%</b></div><div class="ph" id="phs"></div></div>
<div class="row"><button class="gold" id="rn">🎲 Missão aleatória</button><button id="ex">Exportar / importar</button><button id="th">Tema</button></div></div></div></header>
<div class="tb"><div class="ct">
<div class="row"><input type="search" id="q" placeholder="Buscar mod, boss, dungeon, item…"><select id="so"><option value="n">A–Z</option><option value="p">Mais pendentes</option><option value="d">Mais avançados</option></select><button id="gr"></button><button id="ec">Expandir/recolher</button></div>
<div class="row"><span class="lb">Fase</span><span id="fp"></span><span class="lb">Tipo</span><span id="ft"></span><span class="lb">Status</span><span id="fs"></span></div>
<div class="row"><span class="lb">Categoria</span><span id="fc"></span></div></div></div>
<main class="ct"><div id="list"></div>
<details><summary id="ls"></summary><p id="ll"></p></details></main>
<dialog id="dg"><p class="ds">Copie o texto para fazer backup do progresso ou cole um backup e importe.</p><textarea id="ta"></textarea><div class="row"><button class="gold" id="di">Importar</button><button id="dc">Copiar</button><button id="dx">Fechar</button></div></dialog>
<script>
const D={"items": [{"id": "ars-nouveau", "n": "Ars Nouveau", "u": "https://www.curseforge.com/minecraft/mc-mods/ars-nouveau", "c": "Magia", "d": "Crie feitiços combinando glifos; faça familiares e rituais", "a": [["E", "Craftar o Worn Notebook e achar Archwood", "I"], ["E", "Primeiro livro de feitiços e glifos básicos", "I"], ["M", "Montar Source Jars e rede de Source", "I"], ["M", "Criar um familiar", "I"], ["L", "Rituais e Enchanting Apparatus", "I"], ["X", "Armadura de mago nível 3 e feitiço avançado", "I"], ["E", "Domesticar um Starbuncle", "I"], ["M", "Imbuement Chamber e itens imbuídos", "I"], ["M", "Scribes Table para copiar glifos", "I"], ["L", "Derrotar os Wilden (Hunter, Stalker, Guardian)", "B"], ["L", "Automatizar Source com Relays e Sourcelinks", "I"], ["X", "Montar um feitiço com amplificadores e efeitos combinados", "I"], ["M", "Whirlisprig e Wixie", "I"], ["M", "Drygmy e Amethyst Golem", "I"], ["L", "Derrotar o Wilden Chimera", "B"], ["L", "Spell Prism e Arcane Core", "I"]]}, {"id": "ars-elemental", "n": "Ars Elemental", "u": "https://www.curseforge.com/minecraft/mc-mods/ars-elemental", "c": "Magia", "d": "Addon do Ars: escolas elementais, focos e armaduras", "a": [["M", "Escolher uma escola elemental", "I"], ["L", "Fabricar focos elementais", "I"], ["X", "Armadura elemental completa", "I"], ["E", "Craftar o primeiro foco elemental", "I"], ["M", "Ganhar proficiência na escola escolhida", "I"], ["L", "Explorar glifos exclusivos do addon", "E"]]}, {"id": "not-enough-glyphs", "n": "Not Enough Glyphs", "u": "https://www.curseforge.com/minecraft/mc-mods/not-enough-glyphs", "c": "Magia", "d": "Glifos extras para o Ars Nouveau", "a": [["M", "Descobrir glifos extras", "I"], ["L", "Usar glifos extras em um feitiço complexo", "I"]]}, {"id": "ars-magica-legacy", "n": "Ars Magica: Legacy", "u": "https://www.curseforge.com/minecraft/mc-mods/ars-magica-legacy", "c": "Magia", "d": "Magia clássica: afinidades, rituais e habilidades", "a": [["E", "Primeiro ritual", "