/www.curseforge.com/minecraft/mc-mods/shatterbyte-lib"}, {"n": "Structure Pool API", "u": "https://www.curseforge.com/minecraft/mc-mods/structure-pool-api"}, {"n": "LibX", "u": "https://www.curseforge.com/minecraft/mc-mods/libx"}, {"n": "Zeta", "u": "https://www.curseforge.com/minecraft/mc-mods/zeta"}, {"n": "Shield API", "u": "https://www.curseforge.com/minecraft/mc-mods/shield-api"}, {"n": "Resourceful Lib", "u": "https://www.curseforge.com/minecraft/mc-mods/resourceful-lib"}, {"n": "RFTools Base", "u": "https://www.curseforge.com/minecraft/mc-mods/rftools-base"}, {"n": "Citadel", "u": "https://www.curseforge.com/minecraft/mc-mods/citadel"}, {"n": "McJtyLib", "u": "https://www.curseforge.com/minecraft/mc-mods/mcjtylib"}, {"n": "CoFH Core", "u": "https://www.curseforge.com/minecraft/mc-mods/cofh-core"}, {"n": "More RPG Library", "u": "https://www.curseforge.com/minecraft/mc-mods/more-rpg-library"}, {"n": "Sophisticated Core", "u": "https://www.curseforge.com/minecraft/mc-mods/sophisticated-core"}, {"n": "EtST Lib", "u": "https://www.curseforge.com/minecraft/mc-mods/etst-lib"}, {"n": "Patchouli", "u": "https://www.curseforge.com/minecraft/mc-mods/patchouli"}, {"n": "FTB Library (NeoForge)", "u": "https://www.curseforge.com/minecraft/mc-mods/ftb-library-forge"}, {"n": "Lionfish API", "u": "https://www.curseforge.com/minecraft/mc-mods/lionfish-api"}, {"n": "Moonlight Lib", "u": "https://www.curseforge.com/minecraft/mc-mods/selene"}, {"n": "Caelus API", "u": "https://www.curseforge.com/minecraft/mc-mods/caelus"}, {"n": "Apothic Attributes", "u": "https://www.curseforge.com/minecraft/mc-mods/apothic-attributes"}, {"n": "AeroBlender", "u": "https://www.curseforge.com/minecraft/mc-mods/aeroblender"}, {"n": "Ranged Weapon API", "u": "https://www.curseforge.com/minecraft/mc-mods/ranged-weapon-api"}, {"n": "Blueprint", "u": "https://www.curseforge.com/minecraft/mc-mods/blueprint"}, {"n": "YUNG’s API (Forge/NeoForge)", "u": "https://www.curseforge.com/minecraft/mc-mods/yungs-api"}, {"n": "playerAnimator", "u": "https://www.curseforge.com/minecraft/mc-mods/playeranimator"}, {"n": "Spell Engine", "u": "https://www.curseforge.com/minecraft/mc-mods/spell-engine"}, {"n": "Cristel Lib", "u": "https://www.curseforge.com/minecraft/mc-mods/cristel-lib"}, {"n": "GeckoLib", "u": "https://www.curseforge.com/minecraft/mc-mods/geckolib"}, {"n": "Spell Power Attributes", "u": "https://www.curseforge.com/minecraft/mc-mods/spell-power"}, {"n": "Architectury API", "u": "https://www.curseforge.com/minecraft/mc-mods/architectury-api"}, {"n": "Brandon’s Core", "u": "https://www.curseforge.com/minecraft/mc-mods/brandons-core"}, {"n": "Echoes Core", "u": "https://www.curseforge.com/minecraft/mc-mods/echoes-core"}, {"n": "Framework", "u": "https://www.curseforge.com/minecraft/mc-mods/framework"}, {"n": "Resourceful Config", "u": "https://www.curseforge.com/minecraft/mc-mods/resourceful-config"}, {"n": "SmartBrainLib (Forge/Fabric/Quilt)", "u": "https://www.curseforge.com/minecraft/mc-mods/smartbrainlib"}, {"n": "ZeroCore 2", "u": "https://www.curseforge.com/minecraft/mc-mods/zerocore"}, {"n": "TerraBlender (Forge)", "u": "https://www.curseforge.com/minecraft/mc-mods/terrablender"}, {"n": "GuideME", "u": "https://www.curseforge.com/minecraft/mc-mods/guideme"}, {"n": "StateObserver", "u": "https://www.curseforge.com/minecraft/mc-mods/stateobserver"}, {"n": "SuperMartijn642’s Config Lib", "u": "https://www.curseforge.com/minecraft/mc-mods/supermartijn642s-config-lib"}, {"n": "SuperMartijn642’s Core Lib", "u": "https://www.curseforge.com/minecraft/mc-mods/supermartijn642s-core-lib"}, {"n": "Modonomicon", "u": "https://www.curseforge.com/minecraft/mc-mods/modonomicon"}, {"n": "Balm", "u": "https://www.curseforge.com/minecraft/mc-mods/balm"}, {"n": "Structure Gel API", "u": "https://www.curseforge.com/minecraft/mc-mods/structure-gel-api"}, {"n": "Valhelsia Core", "u": "https://www.curseforge.com/minecraft/mc-mods/valhelsia-core"}, {"n": "Iron’s Lib", "u": "https://www.curseforge.com/minecraft/mc-mods/irons-lib"}, {"n": "Cloth Config API (Fabric/Forge/NeoForge)", "u": "https://www.curseforge.com/minecraft/mc-mods/cloth-config"}], "order": ["Magia", "Tecnologia", "Dimensões e exploração", "Mobs, combate e loot", "Classes RPG", "Comida e fazenda", "Decoração e cosméticos", "Utilidades e QoL"]},K="imperacraft2-checklist-v2",PH={E:"Early",M:"Mid",L:"Late",X:"End game"},TY={B:"Boss",E:"Exploração",I:"Item/Mecânica"},TI={B:"⚔️",E:"🧭",I:"🔧"};
let st={};try{st=JSON.parse(localStorage.getItem(K)||"{}")||{}}catch(e){}
const save=()=>{try{localStorage.setItem(K,JSON.stringify(st))}catch(e){}};
D.items.forEach(m=>m.A=m.a.map((a,i)=>({p:a[0],t:a[1],y:a[2]||"I",k:m.id+":"+i})));
const ALL=D.items.flatMap(m=>m.A);
let F={c:"Todas",p:"*",y:"*",s:"*"},q="",gr="c",so="n",open=false,lim=0;
const $=id=>document.getElementById(id),esc=s=>s.replace(/&/g,"&amp;").replace(/</g,"&lt;");
const cnt=a=>[a.filter(x=>st[x.k]).length,a.length];
const chips=(el,key,opts)=>{$(el).innerHTML=opts.map(([v,n])=>`<span class="chip${F[key]==v?" on":""}" data-k="${key}" data-v="${v}">${n}</span>`).join("")};
document.addEventListener("click",e=>{const c=e.target.closest(".chip");if(c){F[c.dataset.k]=c.dataset.v;render()}});
$("q").oninput=e=>{q=e.target.value.toLowerCase();render()};$("so").onchange=e=>{so=e.target.value;render()};
$("gr").onclick=()=>{gr=gr=="c"?"f":"c";render()};
$("ec").onclick=()=>{open=!open;document.querySelectorAll(".mc").forEach(c=>c.classList.toggle("col",!open))};
$("th").onclick=()=>{const r=document.documentElement,d=r.dataset.theme?r.dataset.theme=="dark":matchMedia("(prefers-color-scheme:dark)").matches;r.dataset.theme=d?"light":"dark"};
$("rn").onclick=()=>{const l=[...document.querySelectorAll("label.a:not(.done)")];if(!l.length)return;const e=l[Math.floor(Math.random()*l.length)];e.closest(".mc").classList.remove("col");e.scrollIntoView({block:"center",behavior:"smooth"});e.classList.remove("fl");void e.offsetWidth;e.classList.add("fl")};
$("ex").onclick=()=>{$("ta").value=JSON.stringify(st);$("dg").showModal()};$("dx").onclick=()=>$("dg").close();
$("dc").onclick=()=>{$("ta").select();try{document.execCommand("copy")}catch(e){}};
$("di").onclick=()=>{try{const o=JSON.parse($("ta").value);if(o&&typeof o=="object"){st=o;save();$("dg").close();render()}}catch(e){$("ta").value="Texto inválido"}};
const ok=(m,a)=>(F.p=="*"||a.p==F.p)&&(F.y=="*"||a.y==F.y)&&(F.s=="*"||(F.s=="d")==!!st[a.k])&&(!q||(m.n+" "+m.d+" "+a.t+" "+TY[a.y]+" "+PH[a.p]).toLowerCase().includes(q));
function render(){
  const [d,t]=cnt(ALL),p=Math.round(100*d/t);$("rg").style.setProperty("--p",p+"%");$("rp").textContent=p+"%";
  $("phs").innerHTML=Object.keys(PH).map(k=>{const[a,b]=cnt(ALL.filter(x=>x.p==k));return`<div class="pr p${k}"><span>${PH[k]}</span><div class="bar"><i style="width:${100*a/b}%"></i></div><span>${a}/${b}</span></div>`}).join("")+`<div class="ds">${d} de ${t} atividades concluídas</div>`;
  chips("fp","p",[["*","Todas"],...Object.entries(PH)]);chips("ft","y",[["*","Todos"],...Object.entries(TY).map(([k,v])=>[k,TI[k]+" "+v])]);
  chips("fs","s",[["*","Todas"],["n","Pendentes"],["d","Feitas"]]);chips("fc","c",[["Todas","Todas"],...D.order.map(c=>[c,c])]);
  $("gr").textContent="Agrupar: "+(gr=="c"?"categoria":"fase");
  const ms=D.items.filter(m=>F.c=="Todas"||m.c==F.c),gs=gr=="c"?D.order:Object.keys(PH);let h="";
  for(const g of gs){
    let L=ms.filter(m=>gr=="c"?m.c==g:m.A.some(a=>a.p==g)).map(m=>({m,a:m.A.filter(a=>(gr=="c"||a.p==g)&&ok(m,a))})).filter(x=>x.a.length);
    const pr=x=>cnt(x.m.A);
    L.sort(so=="p"?(x,y)=>(pr(y)[1]-pr(y)[0])-(pr(x)[1]-pr(x)[0]):so=="d"?(x,y)=>pr(y)[0]/pr(y)[1]-pr(x)[0]/pr(x)[1]:(x,y)=>x.m.n.localeCompare(y.m.n));
    if(!L.length)continue;const[gd,gt]=cnt(L.flatMap(x=>x.m.A.filter(a=>gr=="c"||a.p==g)));
    h+=`<h2>${gr=="c"?g:PH[g]}<span>${gd}/${gt}</span></h2>`+L.map(({m,a})=>{const[a1,b1]=cnt(m.A);
      return`<div class="mc${a1==b1?" full":""}${open?"":" col"}" data-m="${m.id}"><div class="mh"><div class="sp"><a class="nm" href="${m.u}" target="_blank" rel="noopener">${esc(m.n)}</a><div class="ds">${esc(m.d)}</div></div><div class="bar mp"><i style="width:${100*a1/b1}%;--h:45"></i></div><small class="mp">${a1}/${b1}</small></div><div class="acts"><div class="tl"><button data-x="all">Marcar todas</button><button data-x="none">Limpar</button></div>${a.map(x=>`<label class="a${st[x.k]?" done":""}"><input type="checkbox" data-k="${x.k}"${st[x.k]?" checked":""}><span class="b p${x.p}">${PH[x.p]}</span><span class="ty" title="${TY[x.y]}">${TI[x.y]}</span><span class="tx">${esc(x.t)}</span></label>`).join("")}</div></div>`}).join("");
  }
  $("list").innerHTML=h||'<p class="ds">Nada encontrado com esses filtros.</p>';
}
$("list").addEventListener("click",e=>{
  const mc=e.target.closest(".mc");if(!mc)return;
  const x=e.target.dataset.x;if(x){const m=D.items.find(i=>i.id==mc.dataset.m);m.A.forEach(a=>{if(x=="all")st[a.k]=true;else delete st[a.k]});save();render();return}
  if(e.target.closest(".mh")&&!e.target.closest("a"))mc.classList.toggle("col")});
$("list").addEventListener("change",e=>{const k=e.target.dataset.k;if(!k)return;const mc=e.target.closest(".mc"),was=!mc.classList.contains("col");if(e.target.checked)st[k]=true;else delete st[k];save();render();if(was){const n=document.querySelector(`.mc[data-m="${mc.dataset.m}"]`);if(n)n.classList.remove("col")}});
$("ls").textContent=`Bibliotecas e dependências (${D.libs.length}) – sem atividades próprias`;
$("ll").innerHTML=D.libs.map(l=>`<a href="${l.u}" target="_blank" rel="noopener">${esc(l.n)}</a>`).join(" · ");
$("rs")&&0;render();
</script></body></html>
